/*
 * A359407  Product_{n>=1} (1 + a(n) * x^n) = 1 + Sum_{n>=1} (n * (n + 1) / 2)
 *          * x^n.
 * https://oeis.org/A359407
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  sign, look
 * Formula:   a(n) = n*(n+1)/2 (when the sequence is generated by ∏_{m≥1} (1 +
 *            a(m) x^m) = 1 + ∑_{n≥1} n*(n+1)/2·x^n. The function evaluates
 *            a(n) for n ≥ 1
 * Range:     i8 n <= 13, i16 n <= 25, i32 n <= 45, i64 n <= 87, i128 n <= 169,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The function is memoised: the sequence is computed once up to the
   maximum n requested so far.  Subsequent calls for the same or
   smaller n return the cached value.  If a larger n is requested, the
   sequence is recomputed from scratch up to that n.  This keeps
   intermediate values small and uses only the allowed operators. */

#include <stdlib.h>

static seq_t *seq_cache = NULL;   /* stored a(n) values, 1‑indexed */
static idx_t cache_max  = 0;      /* highest n for which seq_cache is valid */

/* recompute sequence up to max_n (inclusive), storing values in seq_cache.
   Execution time is O(max_n^2). */
static void recompute(idx_t max_n)
{
    seq_t *f = (seq_t *)calloc((size_t)(max_n + 1), sizeof(seq_t));
    if (!f) abort();
    seq_t *new_cache = (seq_t *)calloc((size_t)(max_n + 1), sizeof(seq_t));
    if (!new_cache) abort();

    f[0] = 1;                         /* coefficient of x^0 */

    for (idx_t k = 1; k <= max_n; ++k) {
        seq_t Tk = (seq_t)k * ((seq_t)k + 1) / 2;   /* n*(n+1)/2 */
        seq_t ak = Tk - f[k];                        /* a(k) = Tk - coeff_{k-1}(k) */
        new_cache[k] = ak;

        /* Update higher coefficients using the new a(k).  Loop downward
           to use the old values of f[j-k]. */
        for (idx_t j = max_n; j >= k; --j) {
            f[j] = f[j] + ak * f[j - k];
        }
    }

    /* replace old cache */
    if (seq_cache) free(seq_cache);
    seq_cache = new_cache;
    cache_max  = max_n;
    free(f);
}

seq_t a(idx_t n)
{
    if (n <= 0) return 0;             /* offset 1; 0 is undefined */
    if (n > cache_max) {
        recompute(n);
    }
    return seq_cache[n];
}
